function AccountWorkspace({session}){const lock=useAccountLock(native?null:session?.user.id||null);const hydration=useNativeHydration(session?.user.id||null);if(!hydration.ready)return <div className="account-gate">正在读取 SQLite 工作空间…</div>;if(hydration.error)return <div className="account-gate"><h2>SQLite 读取失败</h2><p>{hydration.error}</p><button className="primary" onClick={()=>location.reload()}>重试</button><button className="secondary" onClick={async()=>{try{download(JSON.stringify(await nativeRecoveryPayload(session?.user.id||null),null,2),"todo-native-recovery.json")}catch(e){alert(String(e))}}}>导出原始恢复数据</button></div>;if(lock==='loading')return <div className="account-gate">正在打开账号工作空间…</div>;if(lock==='busy'||lock==='unsupported')return <div className="account-gate"><h2>{lock==='busy'?'账号工作空间已在另一个标签页打开':'当前浏览器不支持工作空间锁'}</h2><p>为防止本地数据被不同标签页覆盖，请关闭其他标签页后重试，或使用支持 Web Locks 的浏览器。</p><button className="primary" onClick={()=>location.reload()}>重新打开</button><button className="secondary" onClick={()=>cloud.auth.signOut({scope:'local'})}>退出账号</button></div>;return <App key={session?.user.id||"guest"} session={session} hydration={hydration}/> }
function Root(){const {session,ready,error}=useAccount();if(!ready)return <div className="account-gate">正在恢复账号会话…</div>;if(androidNative&&error&&!session)return <div className="account-gate"><h2>Android 安全会话恢复失败</h2><p>可重试，或清除加密登录会话后重新登录；不会删除任务数据。</p><button className="primary" onClick={()=>location.reload()}>重试</button><button className="secondary" onClick={async()=>{if(confirm("清除本机登录会话？任务与积分数据将保留。"))try{await resetAndroidSession(invoke);location.reload()}catch{alert("无法清除安全会话，请检查设备状态。")}}}>清除登录会话</button></div>;return <AccountWorkspace key={session?.user.id||'guest'} session={session}/>}
createRoot(document.getElementById('root')).render(<Root/>);

